SELECT d.PERIODDATE AS `报告期`, c.SEC_SNAME AS `股票简称`, c.SEC_CODE AS `股票代码`, d.CASH_BT AS `每10股派现金红利(元,含税)` FROM STK_DIV_INFO d JOIN GET_A_SEC_CODE c ON d.COMCODE = c.COMCODE AND c.ISVALID = 1 WHERE d.ISVALID = 1 AND c.SEC_SNAME LIKE '%中国神华%' AND d.PERIODDATE >= '2023-01-01' AND d.PERIODDATE <= '2023-12-31' AND d.CASH_BT IS NOT NULL ORDER BY d.PERIODDATE DESC, d.DIR_DCL_DATE DESC LIMIT 5;
